## Workaround (client-side Node.js proxy wrapper)

While waiting for a fix on the OpenCode side, here's a practical workaround for anyone using a Rust-based MCP server: wrap the binary in a Node.js JSON-RPC filter that strips the non-standard format values before OpenCode's AJV sees them.

```js
#!/usr/bin/env node
const { spawn } = require('child_process');
const path = require('path');

const NON_STANDARD_FORMATS = new Set(['uint8', 'int8', 'uint16', 'int16', 'uint32', 'int32', 'uint64', 'int64']);

const child = spawn('/path/to/your-mcp-binary', process.argv.slice(2), {
  stdio: ['pipe', 'pipe', 'inherit'],
  env: { ...process.env }
});

process.stdin.on('data', (chunk) => child.stdin.write(chunk));

let buffer = '';
child.stdout.on('data', (chunk) => {
  buffer += chunk.toString();
  const lines = buffer.split('\n');
  buffer = lines.pop();
  for (const line of lines) {
    if (!line.trim()) continue;
    try {
      process.stdout.write(JSON.stringify(stripFormats(JSON.parse(line))) + '\n');
    } catch {
      process.stdout.write(line + '\n');
    }
  }
});

child.on('close', (code) => process.exit(code));

function stripFormats(obj) {
  if (Array.isArray(obj)) return obj.map(stripFormats);
  if (obj && typeof obj === 'object') {
    const result = {};
    for (const [k, v] of Object.entries(obj)) {
      if (k === 'format' && NON_STANDARD_FORMATS.has(v)) continue;
      result[k] = stripFormats(v);
    }
    return result;
  }
  return obj;
}
```

Point your `opencode.jsonc` `command` at this script instead of the binary. The filter intercepts JSON-RPC stdout and removes all Rust integer format annotations before OpenCode validates the schema.

Tested on `tmux-mcp-rs` v0.4.0 — eliminates all `unknown format "uint64"` warnings on startup.

The cleanest fix would still be option 1 from the issue (strip in OpenCode's MCP tool registration layer), since this workaround has to be applied per-MCP-server.
